<template><AppLayout page-title="Mon profil"><div class="card"><h2>Informations personnelles</h2><div v-if="message" class="alert alert-success" style="margin:16px 0">{{message}}</div><div class="form-grid"><label>Prénom<input class="input" v-model="form.first_name"></label><label>Nom<input class="input" v-model="form.last_name"></label><label>Email<input class="input" :value="auth.user?.email" disabled></label><label>Téléphone<input class="input" v-model="form.phone"></label></div><button class="btn btn-primary" @click="save" :disabled="saving">{{saving?'Enregistrement…':'Enregistrer'}}</button></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {useAuthStore} from '@/stores/auth';import {supabase} from '@/lib/supabase';const auth=useAuthStore();const saving=ref(false),message=ref('');const form=ref({first_name:'',last_name:'',phone:''});onMounted(()=>{form.value.first_name=String(auth.profile?.first_name||'');form.value.last_name=String(auth.profile?.last_name||'');form.value.phone=String(auth.profile?.phone||'')});async function save(){if(!auth.user)return;saving.value=true;message.value='';const {error}=await supabase.from('profiles').update(form.value).eq('id',auth.user.id);saving.value=false;if(error)message.value=error.message;else{await auth.fetchProfile();message.value='Profil mis à jour.'}}</script>
